import * as THREE from 'three';
import {CupMotion} from './cup-motion.js';
import {findPath,blocked,scoreRun} from './planner.js';
import {makePlan,SCENES,validatePlan} from './data.js';
const V=THREE.Vector3;
const ease=t=>t*t*(3-2*t);
export class Simulator{
 constructor(world,onChange,onLog){this.world=world;this.onChange=onChange;this.onLog=onLog;this.speed=1;this.mode='practice';this.keys=new Set();this.frames=[];this.records=[];this.historyStorageAvailable=true;try{this.records=JSON.parse(localStorage.getItem('field-studio-records')||'[]');}catch{this.records=[];this.historyStorageAvailable=false;}this.setup('warehouse','sort',2);}
 setup(scene,preset,table=2,seed=1){this.scene=scene;this.preset=preset;this.table=table;this.seed=seed;this.world.load(scene,seed);this.plan=makePlan(scene,preset,table);this.resetState();this.log('场景已就绪，可开始训练或直接选择场景中的物体。','info');this.emit();}
 resetState(){this.manipulation=null;this.manualManipulation=false;this.state='ready';this.index=0;this.elapsed=0;this.distance=0;this.collisions=0;this.blockedCount=0;this.completed=0;this.timer=0;this.current=null;this.route=[];this.routeIndex=0;this.frames=[];this.logs=[];this.recorderTimer=0;this.stepMode=false;this.manualTarget=null;this.keys.clear();this.failure='';this.world.held=null;this.replayIndex=0;this.poseReach=0;this.lastCollisionTime=-10;this.startTime=null;this.recorded=false;}
 reset(){const custom=this.world.obstacles.filter(o=>o.custom).map(o=>({x:o.x,z:o.z}));const plan=structuredClone(this.plan);this.world.load(this.scene,this.seed);custom.forEach(o=>this.world.addObstacle(o.x,o.z));this.resetState();this.plan=plan;this.log('训练已重置。','info');this.emit();}
 start(single=false){if(this.state==='emergency'){this.log('请先点击「解除急停」。','warn');return;}if(this.state==='replay')this.exitReplay();if(this.state==='complete'||this.state==='error'||this.state==='manual')this.reset();const err=validatePlan(this.plan,this.world.entities,this.world.targets);if(err){this.log(err,'error');this.failure=err;this.emit();return;}this.stepMode=single;this.state='running';if(!this.startTime){this.startTime=new Date().toISOString();this.capture();this.log('训练开始 · '+(this.mode==='exam'?'考核模式':'练习模式'),'success');}this.emit();}
 toggle(){if(this.state==='running'){this.state='paused';this.log('训练暂停。','info');this.emit();}else this.start();}
 stop(){this.resumeManual=!!(this.state==='manual'&&this.manipulation);if(this.state==='replay')this.exitReplay();this.state='emergency';this.keys.clear();this.log('急停已触发，运动已停止。','warn');this.emit();}
 release(){if(this.state==='emergency'){this.state=this.resumeManual?'manual':this.startTime?'paused':'ready';this.log('急停已解除。','info');this.emit();}}
 log(text,kind='info'){const entry={time:Number((this.elapsed||0).toFixed(1)),text,kind};this.logs??=[];this.logs.push(entry);this.onLog?.(entry);}
 emit(){this.onChange?.(this);}
 get result(){return scoreRun({completed:this.completed,total:this.plan.length,collisions:this.collisions,blockedCount:this.blockedCount,elapsed:this.elapsed,budget:SCENES[this.scene].time});}
 enterAction(){const p=this.plan[this.index];if(!p){this.finish();return false;}this.current=p;this.timer=0;this.log(p.label,'info');if(p.id==='cup'&&['pick','place'].includes(p.type)){this.manipulation=new CupMotion(this.world,p.type,p.type==='place'?this.world.targets[p.target]:null,p.duration,label=>this.log(label,'info'));if(this.manipulation.error){this.fail(this.manipulation.error);return false;}return true;}if(p.type==='move'){if(!this.navigate(p)){this.fail('目标位置不可达，请调整障碍物或导航点。');return false;}}else if(p.type==='pick'){
   const en=this.world.entities[p.id];if(!en||this.world.held){this.fail('抓取条件不满足。');return false;}const pos=en.mesh.getWorldPosition(new V());if(Math.hypot(pos.x-this.world.robot.position.x,pos.z-this.world.robot.position.z)>1.95){this.fail('机器人距离抓取目标过远，请先编排接近动作。');return false;}this.face(pos.x,pos.z,true);this.actionFrom=pos.clone();this.actionTo=null;
 }else if(p.type==='place'){const t=this.world.targets[p.target];if(this.world.held!==p.id||Math.hypot(t.x-this.world.robot.position.x,t.z-this.world.robot.position.z)>1.95){this.fail('未持有对应物品，或未到达交付区域。');return false;}this.face(t.x,t.z,true);this.world.scene.updateMatrixWorld(true);this.actionFrom=this.world.entities[p.id].mesh.getWorldPosition(new V());this.world.environment.attach(this.world.entities[p.id].mesh);this.actionTo=new V(t.x,t.y,t.z);
 }else if(p.type==='process'){if(!this.world.held){this.fail('加工前需要抓取咖啡杯。');return false;}}
 return true;}
 navigate(p){this.route=findPath({x:this.world.robot.position.x,z:this.world.robot.position.z},{x:p.x,z:p.z},this.world.obstacles);if(!this.route){this.blockedCount++;return false;}this.routeIndex=1;return true;}
 face(x,z,instant=false){const p=this.world.robot.position;const a=Math.atan2(x-p.x,z-p.z);if(instant)this.world.robot.rotation.y=a;else{let delta=a-this.world.robot.rotation.y;delta=Math.atan2(Math.sin(delta),Math.cos(delta));this.world.robot.rotation.y+=delta*.2;}}
 moveRoute(dt){if(this.routeIndex>=this.route.length)return true;const p=this.world.robot.position,t=this.route[this.routeIndex];const d=Math.hypot(t.x-p.x,t.z-p.z),velocity=this.preset==='fragile'? .8:1.35,step=Math.min(d,dt*velocity);if(d<.008){this.routeIndex++;return false;}const nx=p.x+(t.x-p.x)/d*step,nz=p.z+(t.z-p.z)/d*step;
 if(blocked(nx,nz,this.world.obstacles)){this.blockedCount++;this.log('路径受阻，重新计算绕行路线。','warn');const last=this.route.at(-1);const replanned=findPath({x:p.x,z:p.z},last,this.world.obstacles);if(!replanned){this.fail('路径被封堵，训练已暂停。请移除障碍后重置。');return false;}this.route=replanned;this.routeIndex=1;return false;}
 this.face(t.x,t.z);p.x=nx;p.z=nz;this.distance+=step;this.world.pose(step*6,this.world.held?1:0,this.world.entities[this.world.held]?.w||.65);if(step>=d-.001)this.routeIndex++;return this.routeIndex>=this.route.length;}
 update(dt){if(this.state==='manual'){this.updateManual(dt);return;}if(this.state==='replay'){if(this.replayPlaying){this.replayClock+=dt*this.speed;let idx=this.replayIndex;while(idx+1<this.frames.length&&this.frames[idx+1].time<=this.replayClock)idx++;this.seek(idx,false);if(idx===this.frames.length-1)this.replayPlaying=false;}return;}if(this.state!=='running')return;
 const delta=Math.min(dt,.06)*this.speed;this.elapsed+=delta;if(!this.current&&!this.enterAction())return;const p=this.current;if(!p)return;let done=false;
 if(p.type==='move'){done=this.moveRoute(delta);if(done&&p.look)this.face(p.look[0],p.look[1],true);}
 else if(this.manipulation&&p.id==='cup'){const result=this.manipulation.tick(delta);this.distance+=result.distance||0;if(result.error){this.fail(result.error);return;}done=result.done;}
 else{this.timer+=delta;const t=Math.min(1,this.timer/p.duration);if(p.type==='pick'){const en=this.world.entities[p.id];this.poseReach=ease(Math.min(1,t*2));this.world.pose(0,this.poseReach,en.w,1.05,en);if(t>.35){const dest=this.world.holdAnchor.getWorldPosition(new V());dest.y-=en.h/2;en.mesh.position.lerpVectors(this.actionFrom,dest,ease((t-.35)/.65));}if(t>=1)this.world.pick(p.id);}
 if(p.type==='place'){const en=this.world.entities[p.id];en.mesh.position.lerpVectors(this.actionFrom,this.actionTo,ease(t));en.mesh.quaternion.slerp(new THREE.Quaternion(),t*.1);this.world.pose(0,1-t*.7,en.w,1.05,en);if(t>=1)this.world.put(p.id,this.world.targets[p.target]);}
 if(p.type==='process'){this.world.pose(0,1,.4,1.12+Math.sin(t*Math.PI*4)*.025);if(t>.5)this.world.process(p.kind);}
 if(p.type==='wait')this.world.pose(0,this.world.held?1:0);done=t>=1;}
 this.recorderTimer+=delta;if(this.recorderTimer>=.16){this.capture();this.recorderTimer=0;}if(done&&this.state==='running'){this.completed++;this.index++;this.current=null;this.manipulation=null;this.world.pose(0,this.world.held?1:0,this.world.entities[this.world.held]?.w||.6);this.capture();if(this.index>=this.plan.length)this.finish();else if(this.stepMode){this.state='paused';this.stepMode=false;this.emit();}}
 }
 capture(){if(this.frames.length<12000)this.frames.push({time:Number(this.elapsed.toFixed(3)),step:this.index,distance:Number(this.distance.toFixed(3)),world:this.world.snapshot()});}
 finish(){this.state='complete';this.completed=this.plan.length;this.log('全部动作已完成，成绩 '+this.result.score+' 分。','success');this.capture();if(!this.recorded){const r={id:'run-'+Date.now(),createdAt:this.startTime||new Date().toISOString(),scene:this.scene,preset:this.preset,mode:this.mode,elapsed:Math.round(this.elapsed*10)/10,distance:Math.round(this.distance*100)/100,collisions:this.collisions,blockedCount:this.blockedCount,result:this.result,plan:structuredClone(this.plan),logs:structuredClone(this.logs),frames:this.frames,seed:this.seed,table:this.table,obstacles:this.world.obstacles.filter(o=>o.custom).map(o=>({x:o.x,z:o.z}))};this.records.unshift(r);this.records=this.records.slice(0,6);this.recorded=true;this.saveRecords();}this.emit();}
 saveRecords(){try{localStorage.setItem('field-studio-records',JSON.stringify(this.records));this.historyStorageAvailable=true;}catch{this.historyStorageAvailable=false;this.log('浏览器存储空间不足，请导出本次训练记录。','warn');}}
 fail(message){this.state='error';this.failure=message;this.log(message,'error');this.emit();}
 manual(){if(this.manipulation&&this.state==='manual'){this.log('取放动作进行中，可使用急停或重置。','warn');return false;}if(this.state==='replay')this.exitReplay();if(this.state==='running'||this.state==='paused'){this.log('请先重置训练，再进入遥操作。','warn');return false;}if(this.state==='emergency')return false;this.state=this.state==='manual'?'ready':'manual';this.keys.clear();this.manualTarget=null;this.log(this.state==='manual'?'遥操作已开启：WASD 移动，E 抓取 / 放下。':'遥操作已关闭。','info');this.emit();return true;}
 updateManual(dt){if(this.manipulation){const result=this.manipulation.tick(dt);this.distance+=result.distance||0;if(result.error){this.log(result.error,'error');this.manipulation=null;this.manualManipulation=false;}else if(result.done){this.log(this.world.held?'已握住杯柄并抬起咖啡杯。':'杯底落稳，已松手。','success');this.manipulation=null;this.manualManipulation=false;this.emit();}return;}const p=this.world.robot.position;let dx=0,dz=0;if(this.keys.has('w')||this.keys.has('arrowup'))dz-=1;if(this.keys.has('s')||this.keys.has('arrowdown'))dz+=1;if(this.keys.has('a')||this.keys.has('arrowleft'))dx-=1;if(this.keys.has('d')||this.keys.has('arrowright'))dx+=1;if(dx||dz){this.manualTarget=null;const l=Math.hypot(dx,dz),nx=p.x+dx/l*dt*1.6,nz=p.z+dz/l*dt*1.6;if(!blocked(nx,nz,this.world.obstacles)){this.face(nx,nz);this.distance+=dt*1.6;p.x=nx;p.z=nz;this.world.pose(dt*8,this.world.held?1:0,this.world.entities[this.world.held]?.w||.6);}else if(performance.now()-this.lastCollisionTime>1000){this.lastCollisionTime=performance.now();this.collisions++;this.log('碰撞保护：前方存在障碍。','warn');}}
 else if(this.manualTarget){if(this.moveRoute(dt)){this.manualTarget=null;this.world.pose(0,this.world.held?1:0);}}else this.world.pose(0,this.world.held?1:0,this.world.entities[this.world.held]?.w||.6);}
 goTo(x,z){if(this.manipulation&&this.state==='manual'){this.log('请等待取放杯动作完成。','warn');return false;}if(this.state==='emergency')return false;if(this.state==='running'||this.state==='paused'){this.log('请先重置，再进行自由导航。','warn');return false;}if(this.state==='replay')this.exitReplay();this.state='manual';if(!this.navigate({x,z})){this.log('该位置被障碍占用，请选择空地。','warn');this.emit();return false;}this.manualTarget={x,z};this.log('导航至选定位置。','info');this.emit();return true;}
 interact(){if(this.state!=='manual'){this.log('请先开启遥操作。','warn');return;}const p=this.world.robot.position;
 if(this.world.entities.cup){
  if(this.manipulation){this.log('取放杯动作正在进行。','info');return;}
  let target=null,kind=this.world.held?'place':'pick';
  if(kind==='pick'){
   const pos=this.world.entities.cup.mesh.getWorldPosition(new V());if(Math.hypot(pos.x-p.x,pos.z-p.z)>1.9){this.log('请先接近取杯区，再按 E 开始伸手取杯。','warn');return;}
  }else{
   target=Object.values(this.world.targets).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0];
   if(!target||Math.hypot(target.x-p.x,target.z-p.z)>1.9){this.log('请走到餐桌旁，再按 E 放杯。','warn');return;}
  }
  const motion=new CupMotion(this.world,kind,target,4,label=>this.log(label,'info'));
  if(motion.error){this.log(motion.error,'warn');return;}
  this.manipulation=motion;this.manualManipulation=true;this.manualTarget=null;this.keys.clear();this.emit();return;
 }
 if(this.world.held){const id=this.world.held;const en=this.world.entities[id];let target=Object.values(this.world.targets).sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0];if(!target||Math.hypot(target.x-p.x,target.z-p.z)>1.9){const dir=new V(0,0,1).applyAxisAngle(new V(0,1,0),this.world.robot.rotation.y);const x=p.x+dir.x*.85,z=p.z+dir.z*.85;if(blocked(x,z,this.world.obstacles,.1)){this.log('放置空间不足，请移至空旷位置。','warn');return;}target={x,y:.04,z};}this.world.put(id,target);this.log('已放下 '+en.name,'success');}else{const nearest=Object.values(this.world.entities).map(en=>({en,pos:en.mesh.getWorldPosition(new V())})).filter(o=>Math.hypot(o.pos.x-p.x,o.pos.z-p.z)<1.9).sort((a,b)=>a.pos.distanceTo(p)-b.pos.distanceTo(p))[0];if(!nearest){this.log('请接近物体后再抓取（1.9 米以内）。','warn');return;}this.face(nearest.pos.x,nearest.pos.z,true);this.world.pick(nearest.en.id);this.log('已抓取 '+nearest.en.name,'success');}this.emit();}
 enterReplay(record=null){if(record){this.setup(record.scene,record.preset,record.table,record.seed);record.obstacles?.forEach(o=>this.world.addObstacle(o.x,o.z));this.plan=structuredClone(record.plan);this.mode=record.mode;this.startTime=record.createdAt;this.logs=structuredClone(record.logs||[]);this.frames=record.frames;this.elapsed=record.elapsed;this.distance=record.distance;this.completed=this.plan.length;this.collisions=record.collisions;this.blockedCount=record.blockedCount;this.state='complete';this.recorded=true;}if(!this.frames.length){this.log('完成一段训练后即可回放。','warn');return false;}if(this.state==='replay')return true;this.resumeState=this.state==='running'?'paused':this.state;this.resumeSnapshot=this.world.snapshot();this.state='replay';this.replayPlaying=false;this.replayClock=0;this.seek(0);this.log('进入轨迹回放，可拖动时间轴。','info');this.emit();return true;}
 seek(index,resetClock=true){if(this.state!=='replay'&&!this.enterReplay())return;this.replayIndex=Math.max(0,Math.min(this.frames.length-1,index));const f=this.frames[this.replayIndex];this.world.restore(f.world);if(resetClock)this.replayClock=f.time;}
 exitReplay(){if(this.state!=='replay')return;this.world.restore(this.resumeSnapshot);this.world.reattachHeld();this.state=this.resumeState==='complete'?'complete':'paused';this.replayPlaying=false;this.emit();}
 exportRecord(){return {format:'embodied-studio-run',version:1,scene:this.scene,preset:this.preset,table:this.table,seed:this.seed,elapsed:this.elapsed,distance:this.distance,result:this.result,plan:this.plan,logs:this.logs,frames:this.frames,createdAt:this.startTime,collisions:this.collisions,blockedCount:this.blockedCount};}
}
